function isPalindrome(s: string): boolean {
  // Проверка: символ — латинская буква или цифра
  const isAlnum = (c: string): boolean => /[a-z0-9]/i.test(c);

  let left = 0;
  let right = s.length - 1;

  while (left < right) {
    // Пропускаем «мусор» слева и справа, не создавая новую строку
    if (!isAlnum(s[left])) {
      left++;
      continue;
    }
    if (!isAlnum(s[right])) {
      right--;
      continue;
    }

    // Сравниваем без учёта регистра
    if (s[left].toLowerCase() !== s[right].toLowerCase()) {
      return false;
    }

    // Символы совпали — сдвигаем оба указателя к центру
    left++;
    right--;
  }

  // Указатели встретились, расхождений не было
  return true;
}

// Время: O(n) — каждый символ просматривается не более одного раза
// Память: O(1) — без копии очищенной строки
